from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text());tt=json.loads((P/'titles.json').read_text())
def p(a,k,t):e[f'A{a:04d}-B{k:04d}']=t
p(562,2,'“异形”（Xenos）是帝国使用的术语，从人类立场看，相当于“外星异族”，泛指非人类、来自地外的智慧物种。')
p(562,4,'Various races of Xenos 不同的异形种族')
p(562,7,'主要的异形种族包括欧克蛮人、灵族、黑暗灵族、泰伦虫族、太空死灵与钛族。它们都对人类的生存及其统治地位构成重大威胁。银河还存在无数其他种族，但相较这些主要势力，影响都小得多。')
p(562,9,'帝国认定，人类才是整个银河的正统统治者。帝国信条要求，凡被视为威胁人类生存的异形，都必须受到遏制或遭到消灭。异形与变种人、异端、离经叛道者一样，被帝国视为人类之敌，因为帝国认为他们威胁着人类存续。')
p(562,11,'帝国探索者每年都会发现新的异形种族与文明。对其中大部分，帝国或置之不理，或加以封锁；若构成威胁，则予以清除。帝国历史上曾与许多危险异形展开旷日持久的战争，大多最终取胜，但有时也只能遏制威胁，无法根除。')
p(562,13,'Various races of Xenos 不同的异形种族')
p(562,14,'Interactions with Xenos 与异形的往来')
p(562,16,'虽然与异形友好往来几乎不可想象，行商浪人却获准与它们交换货物、开展贸易。')
p(562,19,'尽管充满恐惧与仇恨，帝国偶尔仍会与灵族缔结短期军事联盟。此事不常见，却也并非没有先例，通常是为对抗混沌、泰伦虫族或欧克蛮人等共同敌人。帝国海军、帝国卫队，甚至星际战士分遣队，都曾与灵族并肩作战。哥特战争便是一例：帝国与安-伊奥卢斯方舟世界结盟，共同对抗掠夺者阿巴顿。关于钛族，本篇记载双方曾短暂停战，但没有结成临时联盟。')
p(562,22,'一些人类组织，包括审判庭的某些派系、个别导航员家族与光照会，甚至同灵族维系着秘密交易和联盟。这些协定受到严密保密，因为帝国内更保守的势力会将其视为叛国。“伊莎女巫会”便是其中一例。')
p(562,25,'某些人物，如血鸦的加百列·安杰罗斯连长，与特定灵族有过较友好的接触。血鸦尤其如此：战团历来与灵族维系着性质不明的往来，参与各方出于显而易见的原因，都严格保密。讽刺的是，这种保密也可能反过来，成为血鸦对自身历史所知甚少的原因之一。')
p(562,28,'非法的友好往来也可能扩大规模。只要收益足够诱人，一些帝国总督便会无视法律，与异形贸易。许多异形物品被走私入帝国，并在境内流通。异域武器、知识典籍、毒药，以及用来除掉政敌的异形装置，都深受部分见惯奢靡、追求新刺激的权贵追捧，在某些圈子里颇为常见。太空猿猴制造的“死亡蜘蛛”便是一例，它使用银河中最致命的毒药之一——扎塔克斯。某些帝国派系也会偶尔使用异形武器。')
p(562,30,'有些总督甚至雇用异形佣兵，以巩固自己的统治。')
p(562,32,'钛族有意助长这类往来，同邻近帝国星系贸易，并传播上上善道的理念。因此，极限星域边疆已有极少数帝国总督脱离帝国，率领自己治下的世界与星系，转而效忠钛帝国。')
p(562,33,'Xenos and Chaos 异形与混沌')
p(562,35,'不同异形种族与混沌的关系，各有差异。太空死灵等种族，由其本质决定，完全不受混沌腐化影响。钛族则似乎在很大程度上不易遭腐化，不过这种抵抗力多与其社会性质有关。另一些种族已彻底堕落。受到混沌影响、腐化的种族，包括灾祸之子、尤瓦斯、萨鲁提、格雷尔与泽纳克。')
tt['562']='异形 Xenos'
p(564,2,'冉丹（Rangda，亦作 Rangdan），又称冉丹食脑者或冉丹食骨者，是帝国在大远征期间遭遇的凶暴而强大的异形种族。据称，他们来自一颗同名母星。')
p(564,5,'第五军团第一百零五先锋连最先在银河北缘遭遇冉丹。帝国将其视为重大威胁，由阿斯塔特第一军团投入作战。冉丹灭绝战争期间，敌军从银河北部与东部入侵。帝国付出惨重代价，才将他们击退，黑暗天使尤受重创；这是荷鲁斯之乱前帝国经历的最血腥战争。帝国后来宣称，在第三次冉丹灭绝战争中，已灭尽该种族并摧毁其母星系，但相关记载彼此严重矛盾。帝国档案很可能有意或无意地，将阿德维克斯-莫尔斯误标为冉丹首都星“冉丹”。')
p(564,8,'冉丹被描述为拥有“史洛斯式的杀戮心智”，这暗示他们可能是史洛斯的奴役种族。确实曾有人见到史洛斯尾随冉丹，收割死者与沿途遇见的幸存者。冉丹的拟态能力令人畏惧，舰船外观也凶狠狰狞：尖刺与连枷如金属触手般拖曳在舰后，使其宛如水母。据说，冉丹精锐足以匹敌星际战士，武器甚至可能优于帝国装备，并有个人能量护盾保护。他们偏好先驱使庞大的奴隶大军消耗敌人，再择定时机与地点亲自出击。战役由“战帅”统领，而控制奴隶的精英则称为“霸主”。')
p(564,10,'冉丹战舰以“暗影爆破炮”发射带放射性的电磁轰击，名称来自受害者被击杀后留下的不祥阴影。他们还能建造巨大的人造战争卫星，由数百万名受神经项圈控制的奴隶操纵。')
p(564,13,'冉丹之名可能取自巴厘岛传统神话中的朗达（Rangda）：她是莱亚克群魔的女王。')
p(565,2,'莱尔是一种非人形异族。在荷鲁斯之乱前，帝皇之子随第二十八远征舰队征战，将莱尔及其星球莱兰一并消灭。这场战役后来被称为“莱兰清洗”。')
p(565,5,'莱尔都有蛇形下半身，头部则像昆虫，具有昆虫式颚部。他们会通过基因与化学改造，使个体的身体适应指定职能；这种做法令药剂师法比乌斯·拜尔着迷。已知战士形态包括空战、陆战与水战类型。他们使用能发射绿色能量束的臂铠，足以轻易贯穿星际战士的战甲；还装备充能利刃，连终结者护甲也无法抵挡。')
p(565,7,'莱尔狂热崇拜色孽，对莱兰的清洗，最终成为福格瑞姆及其军团堕入混沌的深层原因。')
p(565,9,'法比乌斯·拜尔后来发现，莱尔在个体出生之前便开始进行基因强化，使其能够最大限度地胜任日后承担的职责。他随后利用对莱尔生理的研究，强化了许多帝皇之子战士。')
p(565,13,'小说《福格瑞姆》将此事安排在帝皇被置于黄金王座之前；而较早的英国版《白矮人》第255期，却记载其发生于893.M31，远晚于021.M31的二次建军。')
n.update({'A0562-B0002':'Xenos 全书统一异形，原异型为异写；sentient species 为智慧物种，不是佛学意义的有情。','A0562-B0019':'关于钛族没有军事联盟的断言仅保留为本篇所引资料的范围，不扩写为覆盖所有出版时期的结论。','A0562-B0022':'Illuminati 与0023统一光照会；Navigator统一导航员，Coven of Isha 暂沿伊莎女巫会待核。','A0562-B0025':'Gabriel Angelos 与0318统一加百列·安杰罗斯；Captain是原文此处采用的当时职衔，不用后来的战团长身份替换。','A0562-B0028':'jaded elite 指厌倦既有享乐的权贵，原译疲惫的精英阶层失去社会语境；Jokaero不是死亡蜘蛛本身的动物种类。','A0564-B0002':'Rangda 与 Rangdan 在本篇指同族，中文统一冉丹；词源中的巴厘神话名字单列朗达。','A0564-B0010':'神经项圈控制的是奴隶，再由奴隶操纵战争卫星，原译颠倒施受关系。','A0564-B0013':'原文 probably 表示名称来源推测，中文保留可能，不标为官方词源确认。','A0565-B0005':'energized blades 只明确刃上有能量，不擅限定电能；mandibular features 根据昆虫头部语境译颚部。','A0565-B0013':'英文明确列出两种出版来源的年代冲突，均保留；entombment 依黄金王座语境不译普通葬礼式安葬。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Xenos','异形'),("T'au",'钛族'),('Greater Good','上上善道'),('An-Iolus','安-伊奥卢斯'),('Coven of Isha','伊莎女巫会'),('Jokaero','太空猿猴'),('Jokaero death spider','太空猿猴死亡蜘蛛'),('zarthax','扎塔克斯'),('Bale Childer','灾祸之子'),("Yu'vath",'尤瓦斯'),('Saruthi','萨鲁提'),('Grell','格雷尔'),('Xenarch','泽纳克'),('Rangda','冉丹'),('Rangdan','冉丹'),('Rangdan Cerabvores','冉丹食脑者'),('Rangdan Osseivores','冉丹食骨者'),('Slaugth','史洛斯'),('Shadow Blasters','暗影爆破炮'),('Laer','莱尔'),('Laeran','莱兰'),('Cleansing of Laeran','莱兰清洗')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0562、0564—0565','依本篇具体语义与现稿统一；阵营完整名及人物官译另按已有词表。'])))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n),('titles.json',tt)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{562,564,565};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
print('complete562,564,565',len(e),'edits')
